var items = $input.all();
var output = [];

for (var i = 0; i < items.length; i++) {
  var row = items[i].json || {};
  var p = row.product || {};

  var title = p.title || "بدون عنوان";
  var price = p.price_toman ? p.price_toman.toLocaleString('fa-IR') + " تومان" : "نامشخص";
  var discount = p.discount_percent ? p.discount_percent + "%" : "بدون تخفیف";
  var rating = p.rating_stars ? p.rating_stars : "ثبت نشده";
  var seller = p.seller || "نامشخص";
  var url = p.url || "";

  // ساخت متن پیام جذاب و خوانا برای کاربر
  var messageText = 
    "📦 *محصول پیشنهادی:*\n" +
    title + "\n\n" +
    "💰 قیمت: " + price + "\n" +
    "🏷 تخفیف: " + discount + "\n" +
    "⭐ امتیاز: " + rating + "\n" +
    "🏢 فروشنده: " + seller + "\n" +
    (url ? "🔗 [مشاهده و خرید در دیجی‌کالا](" + url + ")" : "");

  output.push({
    json: {
      chat_id: row.chat_id,
      text: messageText,
      parse_mode: "Markdown"
    }
  });
}

// اگر هیچ محصولی نبود، یک پیام مناسب بده
if (output.length === 0) {
  var sampleRow = items.length > 0 ? items[0].json : {};
  output.push({
    json: {
      chat_id: sampleRow.chat_id || 1583910231,
      text: "❌ متأسفانه کالایی با شرایط مشخص‌شده یافت نشد.",
      parse_mode: "Markdown"
    }
  });
}

return output;

var inputItems = $input.all();
var raw = "";

if (
  inputItems.length > 0 &&
  inputItems[0].json &&
  typeof inputItems[0].json.data === "string"
) {
  raw = inputItems[0].json.data;
}

if (!raw) {
  throw new Error(
    "متن پاسخ MCP در فیلد data پیدا نشد. ورودی HTTP - MCP Digikala را بررسی کنید."
  );
}

// اطلاعات پیام را از نود وب‌هوک بگیر، نه از خود Extract-Data
var webhookItems = $("bale-message").all();
var webhookJson = {};

if (webhookItems.length > 0 && webhookItems[0].json) {
  webhookJson = webhookItems[0].json;
}

var body = webhookJson.body || {};
var message = body.message || {};
var chat = message.chat || {};

var chatId = chat.id || "";
var originalText = message.text || "";

// پاسخ SSE را بخوان
var lines = raw.split(/\r?\n/);
var payload = null;
var parseErrors = [];

for (var i = 0; i < lines.length; i++) {
  var line = lines[i].trim();

  if (line.indexOf("data:") === 0) {
    var eventData = line.substring(5).trim();

    if (!eventData || eventData === "[DONE]") {
      continue;
    }

    try {
      var eventJson = JSON.parse(eventData);

      if (
        eventJson.result &&
        eventJson.result.content &&
        eventJson.result.content.length > 0 &&
        eventJson.result.content[0].text
      ) {
        var text = eventJson.result.content[0].text;
        payload = JSON.parse(text);
        break;
      }
    } catch (error) {
      parseErrors.push(error.message);
    }
  }
}

if (!payload) {
  throw new Error(
    "پاسخ محصولات از SSE استخراج نشد. " +
    (parseErrors.length ? "جزئیات: " + parseErrors.join(" | ") : "")
  );
}

if (!payload.items || !Array.isArray(payload.items)) {
  throw new Error(
    "آرایهٔ items در پاسخ MCP پیدا نشد. ساختار پاسخ MCP را بررسی کنید."
  );
}

// هر محصول را به یک آیتم جدا تبدیل کن
var output = [];

for (var j = 0; j < payload.items.length; j++) {
  output.push({
    json: {
      product: payload.items[j],
      chat_id: chatId,
      original_text: originalText
    }
  });
}

if (output.length === 0) {
  return [{
    json: {
      message: "پاسخ MCP محصولی برنگرداند.",
      chat_id: chatId,
      original_text: originalText
    }
  }];
}

return output;
